  "javaHelp": [
    {
      "id": "J01",
      "trigger": "Array syntax blocks a solution",
      "revise": "Index bounds, array length, swaps, loops; empty input",
      "example": "int[] a = {1, 2}; int n = a.length;",
      "url": "https://dev.java/learn/language-basics/"
    },
    {
      "id": "J02",
      "trigger": "String handling blocks a solution",
      "revise": "equals vs ==; immutability; StringBuilder; ASCII assumptions",
      "example": "StringBuilder out = new StringBuilder(); out.append('a');",
      "url": "https://dev.java/learn/"
    },
    {
      "id": "J03",
      "trigger": "Need lookup, counting or uniqueness",
      "revise": "HashMap, getOrDefault, HashSet; equals/hashCode for custom keys",
      "example": "counts.put(x, counts.getOrDefault(x, 0) + 1);",
      "url": "https://dev.java/learn/api/collections-framework/"
    },
    {
      "id": "J04",
      "trigger": "Large totals or boundary arithmetic",
      "revise": "int vs long; promote before multiply; safe binary-search midpoint",
      "example": "long product = 1L * a * b; int mid = lo + (hi - lo) / 2;",
      "url": "https://dev.java/learn/language-basics/"
    },
    {
      "id": "J05",
      "trigger": "Need ordering beyond ascending numbers",
      "revise": "Arrays.sort, Comparator, deterministic ties; avoid a-b overflow",
      "example": "Arrays.sort(items, (a,b) -> Integer.compare(a.score, b.score));",
      "url": "https://dev.java/learn/api/collections-framework/"
    },
    {
      "id": "J06",
      "trigger": "Need nodes or domain objects",
      "revise": "Small classes; constructors; reference aliasing; null",
      "example": "class Node { int value; Node next; Node(int v) { value = v; } }",
      "url": "https://dev.java/learn/classes-objects/"
    },
    {
      "id": "J07",
      "trigger": "Need a stack or queue",
      "revise": "ArrayDeque push/pop vs offer/poll; empty behavior; no null elements",
      "example": "Deque<Integer> q = new ArrayDeque<>(); q.offer(1); q.poll();",
      "url": "https://dev.java/learn/api/collections-framework/"
    },
    {
      "id": "J08",
      "trigger": "Recursive state behaves strangely",
      "revise": "Base case, call stack, backtrack undo; copy a list when saving a result",
      "example": "answers.add(new ArrayList<>(path));",
      "url": "https://dev.java/learn/"
    },
    {
      "id": "J09",
      "trigger": "Bit operations produce unexpected values",
      "revise": "&, |, ^, <<, >> and >>>; signed 32-bit int; mask widths",
      "example": "boolean isPower = n > 0 && (n & (n - 1)) == 0;",
      "url": "https://dev.java/learn/language-basics/"
    },
    {
      "id": "J10",
      "trigger": "Need next-smallest or next-largest",
      "revise": "PriorityQueue comparator, offer/poll/peek; iteration is not sorted",
      "example": "PriorityQueue<Integer> minHeap = new PriorityQueue<>();",
      "url": "https://dev.java/learn/api/collections-framework/"
    },
    {
      "id": "J11",
      "trigger": "Need graph adjacency and visited state",
      "revise": "List<List<Integer>>, boolean[], queues; avoid deep recursion overflow",
      "example": "List<List<Integer>> graph = new ArrayList<>();",
      "url": "https://dev.java/learn/api/collections-framework/"
    },
    {
      "id": "J12",
      "trigger": "DP storage or sentinels cause bugs",
      "revise": "Arrays.fill; array dimensions; initialize unreachable states safely",
      "example": "Arrays.fill(dp, amount + 1); dp[0] = 0;",
      "url": "https://dev.java/learn/"
    }
  ],
